using System;using System.Collections.Generic;public class BalancedTernaryTreeNode{public int Value;public BalancedTernaryTreeNode Left;public BalancedTernaryTreeNode Middle;public BalancedTernaryTreeNode Right;public BalancedTernaryTreeNode(int value){Value=value;Left=null;Middle=null;Right=null;}}public class BalancedTernaryTree{private BalancedTernaryTreeNode root;public BalancedTernaryTree(){root=null;}public void Insert(int value){root=Insert(root,value);}private BalancedTernaryTreeNode Insert(BalancedTernaryTreeNode node,int value){if(node==null){return new BalancedTernaryTreeNode(value);}if(value<node.Value){node.Left=Insert(node.Left,value);}else if(value>node.Value){node.Right=Insert(node.Right,value);}else{node.Middle=Insert(node.Middle,value);}return Balance(node);}public void Delete(int value){root=Delete(root,value);}private BalancedTernaryTreeNode Delete(BalancedTernaryTreeNode node,int value){if(node==null){return null;}if(value<node.Value){node.Left=Delete(node.Left,value);}else if(value>node.Value){node.Right=Delete(node.Right,value);}else{if(node.Middle!=null){node.Middle=Delete(node.Middle,value);}else if(node.Left!=null){node=node.Left;}else if(node.Right!=null){node=node.Right;}else{node=null;}}return Balance(node);}public bool Search(int value){return Search(root,value);}private bool Search(BalancedTernaryTreeNode node,int value){if(node==null){return false;}if(value<node.Value){return Search(node.Left,value);}else if(value>node.Value){return Search(node.Right,value);}return true;}public List<int> InOrderTraversal(){List<int> result=new List<int>();InOrderTraversal(root,result);return result;}private void InOrderTraversal(BalancedTernaryTreeNode node,List<int> result){if(node!=null){InOrderTraversal(node.Left,result);result.Add(node.Value);InOrderTraversal(node.Middle,result);InOrderTraversal(node.Right,result);}}private BalancedTernaryTreeNode Balance(BalancedTernaryTreeNode node){return node;} // Placeholder for balancing logic}